import fs from 'fs';
import path from 'path';
import type {
  UserProfile,
  MedicineReminder,
  Prescription,
  Doctor,
  Appointment,
  CaregiverConnection,
  CaregiverAlert,
  ConnectedDevice,
  DeviceNudge,
  CrossConnectedDevicesResult,
  UserSubscription,
  PlanLimits
} from '../src/types.ts';
import { SEED_DOCTORS, INITIAL_SAMPLE_REMINDERS } from '../src/data/seedData.ts';

export interface CaregiverCodeRecord {
  code: string;
  connectionCode?: string;
  patientUserId: string;
  patientPhone: string;
  patientName: string;
  createdAt: number;
  expiresAt: number;
  used: boolean;
  status: 'active' | 'used' | 'expired';
}

export function normalizePhone(phone: string): string {
  if (!phone) return '';
  return phone.replace(/[^\d+]/g, '');
}

export function phonesMatch(p1: string, p2: string): boolean {
  if (!p1 || !p2) return false;
  if (p1 === p2) return true;
  const n1 = normalizePhone(p1);
  const n2 = normalizePhone(p2);
  if (n1 === n2) return true;
  const dig1 = p1.replace(/\D/g, '');
  const dig2 = p2.replace(/\D/g, '');
  if (dig1 && dig2 && dig1 === dig2) return true;
  if (dig1.length >= 10 && dig2.length >= 10 && dig1.slice(-10) === dig2.slice(-10)) {
    return true;
  }
  return false;
}

export interface IRepository {
  getUserByPhone(phone: string): Promise<UserProfile | null>;
  saveUser(user: UserProfile): Promise<UserProfile>;

  getReminders(phone: string): Promise<MedicineReminder[]>;
  getReminderById(phone: string, id: string): Promise<MedicineReminder | null>;
  saveReminder(phone: string, reminder: MedicineReminder): Promise<MedicineReminder>;
  deleteReminder(phone: string, id: string): Promise<boolean>;

  getPrescriptions(phone: string): Promise<Prescription[]>;
  savePrescription(phone: string, prescription: Prescription): Promise<Prescription>;
  deletePrescription(phone: string, id: string): Promise<boolean>;

  getDoctors(): Promise<Doctor[]>;
  saveDoctor(doctor: Doctor): Promise<Doctor>;
  deleteDoctor(id: string): Promise<boolean>;

  getAppointments(phone?: string): Promise<Appointment[]>;
  saveAppointment(appointment: Appointment): Promise<Appointment>;

  saveCaregiverCode(record: CaregiverCodeRecord): Promise<void>;
  getActiveCaregiverCode(phone: string): Promise<CaregiverCodeRecord | null>;
  findCaregiverCode(code: string): Promise<CaregiverCodeRecord | null>;
  consumeCaregiverCode(code: string): Promise<CaregiverCodeRecord | null>;

  getConnectionsForPatient(patientPhone: string): Promise<CaregiverConnection[]>;
  getConnectionsForCaregiver(caregiverPhone: string): Promise<CaregiverConnection[]>;
  getConnectionById(id: string): Promise<CaregiverConnection | null>;
  saveConnection(connection: CaregiverConnection): Promise<CaregiverConnection>;
  deleteConnection(id: string): Promise<boolean>;

  getAlertsForCaregiver(caregiverPhone: string): Promise<CaregiverAlert[]>;
  saveAlert(alert: CaregiverAlert): Promise<CaregiverAlert>;
  resolveAlertsForDose(patientPhone: string, reminderId: string, date: string, time: string): Promise<void>;
  getAllActiveConnections(): Promise<CaregiverConnection[]>;

  // Cross-Connected Device Registry
  registerDevice(device: ConnectedDevice): Promise<ConnectedDevice>;
  updateDeviceHeartbeat(deviceId: string, userPhone?: string): Promise<boolean>;
  getDevicesForUser(phone: string): Promise<ConnectedDevice[]>;
  getCrossConnectedDevices(userPhone: string): Promise<CrossConnectedDevicesResult>;
  saveNudge(nudge: DeviceNudge): Promise<DeviceNudge>;
  getNudgesForUser(phone: string): Promise<DeviceNudge[]>;

  // Subscription & Plan Limits
  getSubscription(phone: string): Promise<UserSubscription>;
  saveSubscription(subscription: UserSubscription): Promise<UserSubscription>;
  cancelSubscription(phone: string): Promise<UserSubscription>;
  checkPlanLimits(phone: string): Promise<PlanLimits>;
}

const DATA_DIR = path.join(process.cwd(), '.data');
const DATA_FILE = path.join(DATA_DIR, 'pharmacare_db.json');

interface DatabaseSchema {
  users: Record<string, UserProfile>;
  reminders: Record<string, MedicineReminder[]>;
  prescriptions: Record<string, Prescription[]>;
  doctors: Doctor[];
  appointments: Appointment[];
  caregiverCodes: CaregiverCodeRecord[];
  connections: CaregiverConnection[];
  alerts: CaregiverAlert[];
  devices: Record<string, ConnectedDevice>;
  nudges: DeviceNudge[];
  subscriptions: Record<string, UserSubscription>;
}

export class JsonFileRepository implements IRepository {
  private data: DatabaseSchema;

  constructor() {
    this.data = this.loadData();
  }

  private loadData(): DatabaseSchema {
    const loaded = {
      users: {},
      reminders: {},
      prescriptions: {},
      doctors: [...SEED_DOCTORS],
      appointments: [],
      caregiverCodes: [],
      connections: [],
      alerts: [],
      devices: {},
      nudges: [],
      subscriptions: {},
    };
    try {
      if (!fs.existsSync(DATA_DIR)) {
        fs.mkdirSync(DATA_DIR, { recursive: true });
      }
      if (fs.existsSync(DATA_FILE)) {
        const raw = fs.readFileSync(DATA_FILE, 'utf-8');
        const parsed = JSON.parse(raw);
        return {
          ...loaded,
          ...parsed,
          devices: parsed.devices || {},
          nudges: parsed.nudges || [],
          subscriptions: parsed.subscriptions || {},
        };
      }
    } catch (e) {
      console.warn('Could not read persistent DB file, initializing fresh:', e);
    }
    return loaded;
  }

  private persist(): void {
    try {
      if (!fs.existsSync(DATA_DIR)) {
        fs.mkdirSync(DATA_DIR, { recursive: true });
      }
      fs.writeFileSync(DATA_FILE, JSON.stringify(this.data, null, 2), 'utf-8');
    } catch (e) {
      console.error('Failed to write to persistent DB file:', e);
    }
  }

  async getUserByPhone(phone: string): Promise<UserProfile | null> {
    let found: UserProfile | null = null;
    if (this.data.users[phone]) {
      found = this.data.users[phone];
    } else {
      for (const key of Object.keys(this.data.users)) {
        if (phonesMatch(key, phone)) {
          found = this.data.users[key];
          break;
        }
      }
    }

    if (found) {
      const sub = await this.getSubscription(phone);
      found.plan = sub.plan;
      found.subscriptionStatus = sub.status;
      found.subscriptionExpiry = sub.expiryDate;
    }
    return found;
  }

  async saveUser(user: UserProfile): Promise<UserProfile> {
    this.data.users[user.mobile] = user;
    this.persist();
    return user;
  }

  async getReminders(phone: string): Promise<MedicineReminder[]> {
    if (this.data.reminders[phone]) {
      return this.data.reminders[phone];
    }
    for (const key of Object.keys(this.data.reminders)) {
      if (phonesMatch(key, phone)) {
        return this.data.reminders[key];
      }
    }
    this.data.reminders[phone] = [...INITIAL_SAMPLE_REMINDERS];
    this.persist();
    return this.data.reminders[phone];
  }

  async getReminderById(phone: string, id: string): Promise<MedicineReminder | null> {
    const list = await this.getReminders(phone);
    return list.find(r => r.id === id) || null;
  }

  async saveReminder(phone: string, reminder: MedicineReminder): Promise<MedicineReminder> {
    let targetKey = phone;
    for (const key of Object.keys(this.data.reminders)) {
      if (phonesMatch(key, phone)) {
        targetKey = key;
        break;
      }
    }
    const list = await this.getReminders(targetKey);
    const idx = list.findIndex(r => r.id === reminder.id);
    if (idx >= 0) {
      list[idx] = reminder;
    } else {
      list.unshift(reminder);
    }
    this.data.reminders[targetKey] = list;
    this.persist();
    return reminder;
  }

  async deleteReminder(phone: string, id: string): Promise<boolean> {
    let targetKey = phone;
    for (const key of Object.keys(this.data.reminders)) {
      if (phonesMatch(key, phone)) {
        targetKey = key;
        break;
      }
    }
    const list = await this.getReminders(targetKey);
    const filtered = list.filter(r => r.id !== id);
    if (filtered.length !== list.length) {
      this.data.reminders[targetKey] = filtered;
      this.persist();
      return true;
    }
    return false;
  }

  async getPrescriptions(phone: string): Promise<Prescription[]> {
    return this.data.prescriptions[phone] || [];
  }

  async savePrescription(phone: string, prescription: Prescription): Promise<Prescription> {
    if (!this.data.prescriptions[phone]) {
      this.data.prescriptions[phone] = [];
    }
    const list = this.data.prescriptions[phone];
    const idx = list.findIndex(p => p.id === prescription.id);
    if (idx >= 0) {
      list[idx] = prescription;
    } else {
      list.unshift(prescription);
    }
    this.persist();
    return prescription;
  }

  async deletePrescription(phone: string, id: string): Promise<boolean> {
    if (!this.data.prescriptions[phone]) return false;
    const initialLen = this.data.prescriptions[phone].length;
    this.data.prescriptions[phone] = this.data.prescriptions[phone].filter(p => p.id !== id);
    if (this.data.prescriptions[phone].length !== initialLen) {
      this.persist();
      return true;
    }
    return false;
  }

  async getDoctors(): Promise<Doctor[]> {
    return this.data.doctors;
  }

  async saveDoctor(doctor: Doctor): Promise<Doctor> {
    const idx = this.data.doctors.findIndex(d => d.id === doctor.id);
    if (idx >= 0) {
      this.data.doctors[idx] = doctor;
    } else {
      this.data.doctors.unshift(doctor);
    }
    this.persist();
    return doctor;
  }

  async deleteDoctor(id: string): Promise<boolean> {
    const initialLen = this.data.doctors.length;
    this.data.doctors = this.data.doctors.filter(d => d.id !== id);
    if (this.data.doctors.length !== initialLen) {
      this.persist();
      return true;
    }
    return false;
  }

  async getAppointments(phone?: string): Promise<Appointment[]> {
    if (phone) {
      return this.data.appointments.filter(a => a.patientPhone === phone);
    }
    return this.data.appointments;
  }

  async saveAppointment(appointment: Appointment): Promise<Appointment> {
    this.data.appointments.unshift(appointment);
    this.persist();
    return appointment;
  }

  async saveCaregiverCode(record: CaregiverCodeRecord): Promise<void> {
    // Invalidate prior codes for this patient
    this.data.caregiverCodes = this.data.caregiverCodes.filter(c => !phonesMatch(c.patientPhone, record.patientPhone));
    this.data.caregiverCodes.push(record);
    this.persist();
  }

  async getActiveCaregiverCode(phone: string): Promise<CaregiverCodeRecord | null> {
    const now = Date.now();
    const found = this.data.caregiverCodes.find(
      c => phonesMatch(c.patientPhone, phone) && !c.used && c.status === 'active' && c.expiresAt > now
    );
    return found || null;
  }

  async findCaregiverCode(code: string): Promise<CaregiverCodeRecord | null> {
    const clean = code.trim();
    // Search newest first
    for (let i = this.data.caregiverCodes.length - 1; i >= 0; i--) {
      const c = this.data.caregiverCodes[i];
      if (c.code === clean || c.connectionCode === clean) {
        return c;
      }
    }
    return null;
  }

  async consumeCaregiverCode(code: string): Promise<CaregiverCodeRecord | null> {
    const clean = code.trim();
    const found = await this.findCaregiverCode(clean);
    if (!found) return null;
    const now = Date.now();
    if (found.used || found.status === 'used' || now >= found.expiresAt) {
      return null;
    }
    found.used = true;
    found.status = 'used';
    this.persist();
    return found;
  }

  async getConnectionsForPatient(patientPhone: string): Promise<CaregiverConnection[]> {
    return this.data.connections.filter(c => phonesMatch(c.patientPhone, patientPhone) && c.status !== 'disconnected');
  }

  async getConnectionsForCaregiver(caregiverPhone: string): Promise<CaregiverConnection[]> {
    return this.data.connections.filter(c => phonesMatch(c.caregiverPhone, caregiverPhone) && c.status !== 'disconnected');
  }

  async getConnectionById(id: string): Promise<CaregiverConnection | null> {
    if (!id) return null;
    const byId = this.data.connections.find(c => c.id === id || (c as any).connectionId === id);
    if (byId) return byId;

    const activeByPhone = this.data.connections.find(c => phonesMatch(c.patientPhone, id) && c.status === 'active');
    if (activeByPhone) return activeByPhone;

    return this.data.connections.find(c => phonesMatch(c.patientPhone, id)) || null;
  }

  async saveConnection(connection: CaregiverConnection): Promise<CaregiverConnection> {
    const idx = this.data.connections.findIndex(c => c.id === connection.id);
    if (idx >= 0) {
      this.data.connections[idx] = connection;
    } else {
      this.data.connections.push(connection);
    }
    this.persist();
    return connection;
  }

  async deleteConnection(id: string): Promise<boolean> {
    const conn = await this.getConnectionById(id);
    if (conn) {
      conn.status = 'disconnected';
      conn.updatedAt = Date.now();
      // Remove any pending alerts for this patient connection
      this.data.alerts = this.data.alerts.filter(
        a => a.connectionId !== conn.id && !phonesMatch(a.patientPhone, conn.patientPhone)
      );
      this.persist();
      return true;
    }
    return false;
  }

  async getAlertsForCaregiver(caregiverPhone: string): Promise<CaregiverAlert[]> {
    return this.data.alerts.filter(a => a.caregiverPhone === caregiverPhone);
  }

  async saveAlert(alert: CaregiverAlert): Promise<CaregiverAlert> {
    const idx = this.data.alerts.findIndex(
      a => a.connectionId === alert.connectionId && a.reminderId === alert.reminderId && a.date === alert.date && a.scheduledTime === alert.scheduledTime
    );
    if (idx >= 0) {
      this.data.alerts[idx] = alert;
    } else {
      this.data.alerts.unshift(alert);
    }
    this.persist();
    return alert;
  }

  async resolveAlertsForDose(patientPhone: string, reminderId: string, date: string, time: string): Promise<void> {
    let changed = false;
    this.data.alerts.forEach(a => {
      if (a.patientPhone === patientPhone && a.reminderId === reminderId && a.date === date && a.scheduledTime === time) {
        a.status = 'taken';
        a.confirmedLater = true;
        a.confirmedAt = Date.now();
        changed = true;
      }
    });
    if (changed) {
      this.persist();
    }
  }

  async getAllActiveConnections(): Promise<CaregiverConnection[]> {
    return this.data.connections.filter(c => c.status === 'active');
  }

  // Cross-Connected Device Registry
  async registerDevice(device: ConnectedDevice): Promise<ConnectedDevice> {
    const now = Date.now();
    const updated: ConnectedDevice = {
      ...device,
      isOnline: true,
      lastSeen: now,
    };
    this.data.devices[device.deviceId] = updated;
    this.persist();
    return updated;
  }

  async updateDeviceHeartbeat(deviceId: string, userPhone?: string): Promise<boolean> {
    const dev = this.data.devices[deviceId];
    if (dev) {
      dev.lastSeen = Date.now();
      dev.isOnline = true;
      if (userPhone && !dev.userPhone) {
        dev.userPhone = userPhone;
      }
      this.persist();
      return true;
    }
    return false;
  }

  async getDevicesForUser(phone: string): Promise<ConnectedDevice[]> {
    const list: ConnectedDevice[] = [];
    const now = Date.now();
    // Device considered online if seen in the last 75 seconds
    const ONLINE_THRESHOLD = 75000;

    for (const d of Object.values(this.data.devices)) {
      if (phonesMatch(d.userPhone, phone)) {
        const isOnline = now - d.lastSeen < ONLINE_THRESHOLD;
        list.push({
          ...d,
          isOnline,
        });
      }
    }
    return list;
  }

  async getCrossConnectedDevices(userPhone: string): Promise<CrossConnectedDevicesResult> {
    const myDevices = await this.getDevicesForUser(userPhone);

    const asPatient = await this.getConnectionsForPatient(userPhone);
    const asCaregiver = await this.getConnectionsForCaregiver(userPhone);
    const allConns = [...asPatient, ...asCaregiver];

    const connectedMembers: CrossConnectedDevicesResult['connectedMembers'] = [];
    const seenConns = new Set<string>();

    for (const c of allConns) {
      if (seenConns.has(c.id)) continue;
      seenConns.add(c.id);

      const isMeThePatient = phonesMatch(c.patientPhone, userPhone);
      const partnerPhone = isMeThePatient ? c.caregiverPhone : c.patientPhone;
      const partnerDevices = await this.getDevicesForUser(partnerPhone);

      connectedMembers.push({
        connectionId: c.id,
        patientName: c.patientName,
        patientPhone: c.patientPhone,
        caregiverName: c.caregiverName,
        caregiverPhone: c.caregiverPhone,
        status: c.status,
        devices: partnerDevices,
      });
    }

    return {
      myDevices,
      connectedMembers,
    };
  }

  async saveNudge(nudge: DeviceNudge): Promise<DeviceNudge> {
    this.data.nudges.unshift(nudge);
    if (this.data.nudges.length > 200) {
      this.data.nudges = this.data.nudges.slice(0, 200);
    }
    this.persist();
    return nudge;
  }

  async getNudgesForUser(phone: string): Promise<DeviceNudge[]> {
    return this.data.nudges.filter(n => phonesMatch(n.toPhone, phone) || phonesMatch(n.fromPhone, phone));
  }

  // Subscription Management
  async getSubscription(phone: string): Promise<UserSubscription> {
    if (!phone) {
      return {
        userId: 'guest',
        phone: '',
        plan: 'free',
        status: 'none',
        startDate: null,
        expiryDate: null,
        billingCycle: null,
        paymentStatus: 'none',
        autoRenew: false,
        updatedAt: Date.now(),
      };
    }

    let foundSub: UserSubscription | null = null;
    let foundKey: string | null = null;

    if (!this.data.subscriptions) {
      this.data.subscriptions = {};
    }

    for (const [key, sub] of Object.entries(this.data.subscriptions)) {
      if (phonesMatch(key, phone) || (sub?.phone && phonesMatch(sub.phone, phone))) {
        foundSub = sub;
        foundKey = key;
        break;
      }
    }

    if (foundSub) {
      // Check if active subscription has expired
      if (foundSub.plan === 'premium' && foundSub.expiryDate && foundSub.expiryDate < Date.now()) {
        foundSub.status = 'expired';
        foundSub.plan = 'free';
        foundSub.autoRenew = false;
        foundSub.updatedAt = Date.now();
        this.persist();
      }
      return foundSub;
    }

    // Default Free plan subscription
    const defaultSub: UserSubscription = {
      userId: phone,
      phone,
      plan: 'free',
      status: 'none',
      startDate: null,
      expiryDate: null,
      billingCycle: null,
      paymentStatus: 'none',
      autoRenew: false,
      updatedAt: Date.now(),
    };
    this.data.subscriptions[phone] = defaultSub;
    this.persist();
    return defaultSub;
  }

  async saveSubscription(subscription: UserSubscription): Promise<UserSubscription> {
    if (!this.data.subscriptions) {
      this.data.subscriptions = {};
    }

    let targetKey = subscription.phone;
    for (const key of Object.keys(this.data.subscriptions)) {
      if (phonesMatch(key, subscription.phone)) {
        targetKey = key;
        break;
      }
    }

    const updatedSub: UserSubscription = {
      ...subscription,
      updatedAt: Date.now(),
    };
    this.data.subscriptions[targetKey] = updatedSub;

    // Sync with UserProfile record if present
    const user = await this.getUserByPhone(subscription.phone);
    if (user) {
      user.plan = updatedSub.plan;
      user.subscriptionStatus = updatedSub.status;
      user.subscriptionExpiry = updatedSub.expiryDate;
      await this.saveUser(user);
    }

    this.persist();
    return updatedSub;
  }

  async cancelSubscription(phone: string): Promise<UserSubscription> {
    const sub = await this.getSubscription(phone);
    sub.status = 'cancelled';
    sub.plan = 'free';
    sub.autoRenew = false;
    sub.updatedAt = Date.now();
    await this.saveSubscription(sub);
    return sub;
  }

  async checkPlanLimits(phone: string): Promise<PlanLimits> {
    const sub = await this.getSubscription(phone);
    const isPremium =
      sub.plan === 'premium' &&
      sub.status === 'active' &&
      (!sub.expiryDate || sub.expiryDate > Date.now());

    const remindersList = await this.getReminders(phone);
    const activeRemindersCount = remindersList.filter((r) => r.active).length;

    const prescriptionsList = await this.getPrescriptions(phone);
    const activePrescriptionsCount = prescriptionsList.length;

    const connectionsList = await this.getConnectionsForPatient(phone);
    const activeCaregiversCount = connectionsList.filter((c) => c.status === 'active').length;

    if (isPremium) {
      return {
        reminders: {
          max: null,
          current: activeRemindersCount,
          canAdd: true,
        },
        prescriptions: {
          max: null,
          current: activePrescriptionsCount,
          canAdd: true,
        },
        caregivers: {
          max: null,
          current: activeCaregiversCount,
          canAdd: true,
        },
      };
    }

    // Free plan limits: 3 reminders, 3 prescriptions, 1 caregiver
    return {
      reminders: {
        max: 3,
        current: activeRemindersCount,
        canAdd: activeRemindersCount < 3,
      },
      prescriptions: {
        max: 3,
        current: activePrescriptionsCount,
        canAdd: activePrescriptionsCount < 3,
      },
      caregivers: {
        max: 1,
        current: activeCaregiversCount,
        canAdd: activeCaregiversCount < 1,
      },
    };
  }
}

export const repository: IRepository = new JsonFileRepository();
